<script setup lang="ts">
import {computed,nextTick,ref,watch} from 'vue';
import {listPolicyView,listPolicyOptions,type ListPolicyView} from './list-policy-view';
import {NAlert,NButton,NCheckbox,NCheckboxGroup,NCollapse,NCollapseItem,NDrawer,NDrawerContent,NForm,NFormItem,NInput,NRadio,NRadioGroup,NSelect,NSpace} from 'naive-ui';
import type {FormInst,FormRules} from 'naive-ui';
import type {ConfigMember} from '../../phase2';
import type {DirectorySubjects} from '../directory/types';
import PackageChannelPolicies from './PackageChannelPolicies.vue';
import {clonePackage,packageUserMode,packageChannelPolicies,resourceName,type PackageEditorValue,type PackageUserMode,type NamedResource} from './capability-package-view';
const props=defineProps<{show:boolean;value:PackageEditorValue;handoffEnabled?:boolean;handoffOptions?:{id:string;name:string;enabled:boolean}[];triggerOptions?:import('./trigger-types').TriggerOption[];resources:NamedResource[];members:ConfigMember[];subjects:DirectorySubjects;base:string;directoryBase?:string;draft?:boolean;busy:boolean;error?:string;notice?:string}>();
const emit=defineEmits<{submit:[value:PackageEditorValue];close:[];upload:[file:File,value:PackageEditorValue];busyChanged:[busy:boolean]}>();
function submission(){const value=clonePackage(form.value);value.directoryAccess.channelPolicies=channelPolicies.value;if(!props.handoffEnabled){delete value.handoffUsageScope;delete value.handoffUsageMode;}return value;}
const form=ref(clonePackage(props.value)),original=ref(''),discard=ref(false),pendingMode=ref<PackageUserMode|null>(null),pendingChannelMode=ref(false),formRef=ref<FormInst|null>(null),queries=ref({allow:false,deny:false,channels:false}),file=ref<File|null>(null),submitting=ref(false);
const busy=computed(()=>props.busy||queries.value.allow||queries.value.deny||queries.value.channels),dirty=computed(()=>JSON.stringify(form.value)!==original.value),userMode=ref<PackageUserMode>(packageUserMode(form.value));
const rules:FormRules={name:{required:true,validator:(_r,v:string)=>!!v?.trim()||new Error('请输入能力包名称'),trigger:['input','blur']}};
const handoffMode=computed({get:()=>form.value.handoffUsageMode??(form.value.handoffUsageScope?'custom':'inherit'),set:value=>{form.value.handoffUsageMode=value;}});
const handoffScope=computed({get:()=>form.value.handoffUsageScope??{mode:'all' as const,allowEmployeeIds:[],denyEmployeeIds:[]},set:value=>{form.value.handoffUsageScope=value;}});
const handoffSelection=computed({get:()=>listPolicyView(handoffScope.value,handoffScope.value.denyEmployeeIds.length),set:(value:ListPolicyView)=>{if(value!=='legacy')handoffScope.value={...handoffScope.value,mode:value==='allowlist'?'allowlist':'all',selectionMode:value};}});
const employeeOptions=computed(()=>(props.handoffOptions??[]).map(e=>({label:e.name+(e.enabled?'':'（停用）'),value:e.id})));
const triggerScope=computed({get:()=>form.value.triggerUsageScope??{mode:'all' as const,allowTriggerIds:[],denyTriggerIds:[]},set:value=>{form.value.triggerUsageScope=value;}});
const triggerSelection=computed({get:()=>listPolicyView(triggerScope.value,triggerScope.value.denyTriggerIds.length),set:(value:ListPolicyView)=>{if(value!=='legacy')triggerScope.value={...triggerScope.value,mode:value==='allowlist'?'allowlist':'all',selectionMode:value};}});
const triggerOptions=computed(()=>(props.triggerOptions??[]).map(t=>({label:t.name+' · '+t.id+(t.enabled?'':'（停用）'),value:t.id})));
const memberOptions=computed(()=>props.members.map(m=>({label:m.displayName,value:m.id})));
const channelPolicies=computed({get:()=>{const saved=form.value.directoryAccess.channelPolicies??[];return [...saved,...packageChannelPolicies(props.value,props.subjects.sources.map(source=>source.sourceId)).filter(policy=>!saved.some(current=>current.sourceId===policy.sourceId))];},set:value=>{form.value.directoryAccess.channelPolicies=value;}});
const kinds=computed(()=>[{label:'私聊',value:'private'},{label:'群聊',value:'group'},...(form.value.conversationKinds?.includes('meeting')?[{label:'会议（历史兼容）',value:'meeting'}]:[])]);
function resourceOptions(kind:NamedResource['kind']){return props.resources.filter(r=>r.kind===kind).map(r=>({label:`${resourceName(r)}${r.kind==='mcp'?` · ${r.allowedTools.length}个工具`:r.kind==='skill'?` · ${r.version}`:''}`,value:r.id,disabled:r.enabled===false}));}
function chosen(kind:NamedResource['kind']){return form.value.resourceIds.filter(id=>props.resources.some(r=>r.id===id&&r.kind===kind));}
function choose(kind:NamedResource['kind'],ids:string[]){const old=new Set(chosen(kind));form.value.resourceIds=[...form.value.resourceIds.filter(id=>!old.has(id)),...ids];}
const missing=computed(()=>form.value.resourceIds.filter(id=>!props.resources.some(r=>r.id===id)));
const grantsBash=computed(()=>props.resources.some(r=>r.kind==='execution'&&r.tools.includes('bash')&&form.value.resourceIds.includes(r.id)));
watch(()=>props.show,show=>{if(show){form.value=clonePackage(props.value);original.value=JSON.stringify(form.value);discard.value=false;pendingMode.value=null;file.value=null;userMode.value=packageUserMode(form.value);}},{immediate:true});
// Upload result updates only the resource selection; never replace unsaved policy edits.
watch(()=>props.value.resourceIds,ids=>{if(props.show)form.value.resourceIds=[...ids];});
watch(()=>queries.value.allow||queries.value.deny||queries.value.channels,value=>emit('busyChanged',value),{flush:'sync'});
function close(){if(busy.value||submitting.value)return;if(dirty.value){discard.value=true;return;}emit('close');}
function changeMode(mode:PackageUserMode){if(busy.value||mode==='legacy'||mode===userMode.value)return;if(userMode.value==='legacy')pendingMode.value=mode;else applyMode(mode);}
function applyMode(mode:PackageUserMode){if(mode==='legacy')return;form.value.mode=mode==='allowlist'?'restrict':'inherit';form.value.userPolicyMode=mode;userMode.value=mode;pendingMode.value=null;}
async function submit(){if(busy.value||submitting.value||pendingMode.value||pendingChannelMode.value)return;submitting.value=true;try{await formRef.value?.validate();}catch{submitting.value=false;return;}if([...form.value.directoryAccess.allow,...form.value.directoryAccess.deny,...channelPolicies.value.flatMap(policy=>[...policy.allow,...policy.deny])].some(r=>!r.conversationKinds.length)){submitting.value=false;return;}emit('submit',submission());await nextTick();if(!props.busy)submitting.value=false;}
watch(()=>props.busy,value=>{if(!value)submitting.value=false;});
function onEscape(event:KeyboardEvent){if(event.defaultPrevented||event.isComposing||event.keyCode===229||(event.target instanceof Element&&event.target.closest('input,textarea,select,[role="combobox"],[role="listbox"],.n-select')))return;event.stopPropagation();event.preventDefault();close();}
</script>
<template><NDrawer :show="show" placement="right" :width="'min(720px, 100vw)'" :mask-closable="false" :close-on-esc="false" @update:show="value=>{if(!value)close()}"><NDrawerContent title="能力包配置" closable @close="close" @keydown.esc="onEscape"><div class="package-editor">
 <NAlert v-if="error" type="error" role="alert">{{ error }}</NAlert><NAlert v-if="notice" type="info">{{ notice }}</NAlert>
 <NAlert v-if="discard" type="warning">丢弃本次未保存的修改？{{ draft?'已保存的向导草稿保持不变。':'已有能力包保持不变。' }}<NSpace><NButton :disabled="busy" @click="discard=false">继续编辑</NButton><NButton :disabled="busy" @click="emit('close')">丢弃修改并返回列表</NButton></NSpace></NAlert>
 <NForm ref="formRef" :model="form" :rules="rules" @submit.prevent="submit"><section><h3>基本信息</h3><NFormItem label="名称" path="name"><NInput v-model:value="form.name" :input-props="{'aria-label':'能力包名称'}" :maxlength="120" :disabled="busy" /></NFormItem><NFormItem label="描述"><NInput v-model:value="form.description" type="textarea" :input-props="{'aria-label':'能力包描述'}" :maxlength="4000" :disabled="busy" placeholder="说明此能力包能完成哪些工作，供交接时选人参考。" /></NFormItem><NCheckbox v-model:checked="form.enabled" :disabled="busy">启用此能力包</NCheckbox></section>
  <section><h3>资源</h3><NFormItem label="Skill（可多选）"><NSelect :value="chosen('skill')" :options="resourceOptions('skill')" multiple filterable :virtual-scroll="false" :disabled="busy" aria-label="能力包Skill" @update:value="ids=>choose('skill',ids)" /></NFormItem><NFormItem label="MCP（可多选）"><NSelect :value="chosen('mcp')" :options="resourceOptions('mcp')" multiple filterable :virtual-scroll="false" :disabled="busy" aria-label="能力包MCP" @update:value="ids=>choose('mcp',ids)" /></NFormItem>
   <p v-for="r in resources.filter(r=>r.kind==='mcp'&&form.resourceIds.includes(r.id))" :key="r.id" class="field-note">{{ resourceName(r) }} · 获准工具：{{ r.kind==='mcp'?r.allowedTools.join('、'):'' }}</p>
   <p v-if="!resources.length" class="field-note">当前无已批准资源；空资源包不代表已接入业务工具。</p>
   <p v-if="missing.length" class="field-note">暂不可用资源仍保留：{{ missing.join('、') }}。不会因目录缺项自动删掉绑定。</p>
   <NCollapse><NCollapseItem title="高级执行工具" name="execution"><NSelect :value="chosen('execution')" :options="resourceOptions('execution')" multiple :virtual-scroll="resources.length>100" :disabled="busy" aria-label="能力包执行工具" @update:value="ids=>choose('execution',ids)" /></NCollapseItem></NCollapse><NAlert v-if="grantsBash" class="bash-permission-note" type="warning">包含 Bash，可运行命令并读写文件，并非只读。本地独立工作目录不是安全沙箱。</NAlert>
   <p class="field-note">资源统一在管理页面创建，能力包仅选择关联已有 Skill 和 MCP。</p>
  </section>
  <section><h3>使用范围</h3><p class="field-note">以员工整体范围为上限；本包拒绝不代表其他包也拒绝。</p><NFormItem label="网页使用者策略"><NRadioGroup :value="userMode" :disabled="busy" aria-label="能力包使用者策略" @update:value="value=>changeMode(value as PackageUserMode)"><NSpace vertical><NRadio value="inherit">继承员工使用范围</NRadio><NRadio value="allowlist">允许名单（白名单）</NRadio><NRadio value="denylist">拒绝名单（黑名单）</NRadio><NRadio v-if="userMode==='legacy'" value="legacy">历史组合策略（保留允许与拒绝）</NRadio></NSpace></NRadioGroup></NFormItem>
   <NAlert v-if="pendingMode" type="warning">切换策略后仅选中名单生效，原名单保留，可能改变包的使用范围。{{ pendingMode==='inherit'?'将继承全部员工使用范围。':pendingMode==='allowlist'?'仅允许项生效；拒绝项保留但不生效；空允许名单无人可用。':'仅拒绝项生效；允许项保留但不生效；其余员工获准使用者可用。' }}<NSpace><NButton :disabled="busy" @click="pendingMode=null">保留原策略</NButton><NButton :disabled="busy" @click="applyMode(pendingMode!)">确认切换策略</NButton></NSpace></NAlert>
   <p class="field-note">网页策略切换保留已填写名单，仅选中名单参与判断。渠道策略在下方分别设置，渠道黑名单始终优先。空白名单无人可用，空黑名单不额外限制员工范围。</p>
   <NAlert v-if="userMode==='legacy'" type="info">原有组合规则保持不变，拒绝优先；只修改资源不会改写名单。</NAlert>
   <template v-if="userMode==='allowlist'||userMode==='legacy'"><NFormItem label="允许平台用户"><NSelect v-model:value="form.allowMemberIds" multiple filterable :virtual-scroll="members.length>100" :options="memberOptions" :disabled="busy" aria-label="包内允许成员" /></NFormItem></template>
   <template v-if="userMode==='denylist'||userMode==='legacy'"><NFormItem label="拒绝平台用户"><NSelect v-model:value="form.denyMemberIds" multiple filterable :virtual-scroll="members.length>100" :options="memberOptions" :disabled="busy" aria-label="包内拒绝成员" /></NFormItem></template>
   <PackageChannelPolicies v-model:policies="channelPolicies" :subjects="subjects" :base="base" v-bind="directoryBase?{directoryBase}:{}" :draft="draft" :disabled="busy" @busy-changed="v=>queries.channels=v" @pending-changed="v=>pendingChannelMode=v"/>
   <NFormItem label="会话类型"><NCheckboxGroup :value="form.conversationKinds??[]" :disabled="busy" @update:value="value=>{form.conversationKinds=value as PackageEditorValue['conversationKinds']}"><NSpace><NCheckbox v-for="kind in kinds" :key="kind.value" :value="kind.value">{{ kind.label }}</NCheckbox></NSpace></NCheckboxGroup></NFormItem><p v-if="form.conversationKinds===null" class="field-note">旧配置没有包级会话限制；继续沿用原规则，只有明确选择后才收窄。</p><p v-else-if="!form.conversationKinds.length" class="field-note">未选择会话类型：此包不适用于任何会话，保存后无人可用。</p>
  </section><section><h3>自动化任务可用范围</h3><p class="field-note">与使用者和会话类型并列。自动事件不冒充自然人，不使用私聊/群聊规则；仅接受当前员工已配置的自动化任务来源，历史组合规则拒绝优先；切换模式保留名单，仅选中名单生效。</p><NFormItem label="自动化任务使用策略"><NSelect :virtual-scroll="false" v-model:value="triggerSelection" :options="listPolicyOptions(triggerSelection,'当前员工全部自动化任务')" :disabled="busy" aria-label="自动化任务使用策略" /></NFormItem><NFormItem v-if="triggerSelection==='allowlist'||triggerSelection==='legacy'" label="允许的自动化任务"><NSelect :virtual-scroll="false" :value="triggerScope.allowTriggerIds" :options="triggerOptions" multiple filterable :disabled="busy" aria-label="允许的自动化任务" @update:value="v=>{triggerScope={...triggerScope,allowTriggerIds:v}}" /></NFormItem><NFormItem v-if="triggerSelection==='denylist'||triggerSelection==='legacy'" label="拒绝的自动化任务"><NSelect :virtual-scroll="false" :value="triggerScope.denyTriggerIds" :options="triggerOptions" multiple filterable :disabled="busy" aria-label="拒绝的自动化任务" @update:value="v=>{triggerScope={...triggerScope,denyTriggerIds:v}}" /></NFormItem><p v-if="!triggerOptions.length" class="field-note">当前尚无自动化任务。全部模式也适用于之后为此员工新增的自动化任务；已有名单保留。</p></section><section v-if="handoffEnabled"><h3>数字员工交接可用范围</h3><NFormItem label="交接范围来源"><NRadioGroup v-model:value="handoffMode" :disabled="busy"><NSpace><NRadio value="inherit">继承员工接收范围</NRadio><NRadio value="custom">单独设置黑白名单</NRadio></NSpace></NRadioGroup></NFormItem><template v-if="handoffMode==='custom'"><NFormItem label="数字员工交接使用策略"><NSelect :virtual-scroll="false" v-model:value="handoffSelection" :options="listPolicyOptions(handoffSelection,'员工接收范围内全部来源')" :disabled="busy" aria-label="数字员工交接使用策略"/></NFormItem><NFormItem v-if="handoffSelection==='allowlist'||handoffSelection==='legacy'" label="允许交接的员工"><NSelect :virtual-scroll="false" :value="handoffScope.allowEmployeeIds" :options="employeeOptions" multiple filterable :disabled="busy" aria-label="允许交接的员工" @update:value="v=>{handoffScope={...handoffScope,allowEmployeeIds:v}}"/></NFormItem><NFormItem v-if="handoffSelection==='denylist'||handoffSelection==='legacy'" label="拒绝交接的员工"><NSelect :virtual-scroll="false" :value="handoffScope.denyEmployeeIds" :options="employeeOptions" multiple filterable :disabled="busy" aria-label="拒绝交接的员工" @update:value="v=>{handoffScope={...handoffScope,denyEmployeeIds:v}}"/></NFormItem></template><p class="field-note">默认继承员工接收范围，单独名单只能进一步收窄，不能越过员工拒绝；统一只判断直接交接员工。切换模式保留名单，仅选中名单生效。关闭Beta隐藏并保留配置。</p></section><NSpace class="package-editor-actions"><NButton :disabled="busy||submitting" @click="close">返回列表</NButton><NButton attr-type="submit" type="primary" :loading="busy||submitting" :disabled="busy||submitting||!!pendingMode||pendingChannelMode">{{ draft?'保存包草稿':'保存能力包' }}</NButton></NSpace>
 </NForm></div></NDrawerContent></NDrawer></template>
<style scoped>.package-editor{display:grid;gap:1rem}.package-editor section{padding:0.25rem 0 1.5rem;margin-bottom:1.25rem;border-bottom:1px solid var(--subtle)}.package-editor h3{font-size:1rem;margin:0 0 1.25rem}.package-editor-actions{position:sticky;bottom:-16px;padding:1rem 0;background:var(--n-color,#fff);justify-content:flex-end}.skill-upload{margin-top:1.25rem}.skill-upload label{display:grid;gap:0.625rem}.package-editor :deep(.n-tag),.package-editor :deep(.n-base-selection-tag-wrapper){max-width:100%}.package-editor p{overflow-wrap:anywhere}@media(max-width:36.25rem){.package-editor-actions{flex-wrap:wrap}}</style>
